BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;
SELECT json_build_object('read_at',clock_timestamp(),'transaction_read_only',current_setting('transaction_read_only'),
'latest_published_articles',(SELECT json_agg(json_build_object('id',id,'title',title,'locale',locale,'status',status,'published_at',published_at,'updated_at',updated_at) ORDER BY published_at DESC,id) FROM (SELECT id,title,locale,status,published_at,updated_at FROM article WHERE published_at IS NOT NULL ORDER BY published_at DESC LIMIT 10) x),
'recently_updated_articles',(SELECT json_agg(json_build_object('id',id,'title',title,'locale',locale,'status',status,'publish_at',publish_at,'published_at',published_at,'updated_at',updated_at) ORDER BY updated_at DESC,id) FROM (SELECT id,title,locale,status,publish_at,published_at,updated_at FROM article WHERE updated_at>'2026-10-10T17:07:56.462380Z' ORDER BY updated_at DESC LIMIT 20) x),
'publish_tasks_after_deploy',(SELECT json_agg(json_build_object('id',id,'task_type',task_type,'status',status,'requested_at',requested_at,'created_at',created_at,'completed_at',completed_at,'total_count',total_count,'success_count',success_count,'failed_count',failed_count,'skipped_count',skipped_count) ORDER BY requested_at DESC) FROM (SELECT * FROM generic_task WHERE task_type LIKE 'article.publish.%' AND requested_at>'2026-10-10T17:07:56.462380Z' ORDER BY requested_at DESC LIMIT 20) x),
'publish_task_items_after_deploy',(SELECT json_agg(json_build_object('task_id',t.id,'task_type',t.task_type,'item_id',i.id,'item_status',i.status,'target_type',i.target_type,'target_id',i.target_id,'reason',i.result->>'reason','error_code',i.error->>'code','started_at',i.started_at,'finished_at',i.finished_at) ORDER BY t.requested_at DESC,i.id) FROM generic_task t JOIN generic_task_item i ON i.task_id=t.id WHERE t.task_type LIKE 'article.publish.%' AND t.requested_at>'2026-10-10T17:07:56.462380Z'));
COMMIT;
